CAT = "plteoPierwszenstwo"; SEG = "PIE"
# Pierwszeństwo, skrzyżowania, włączanie się do ruchu, pojazdy uprzywilejowane.
# Źródło: PoRD (t.j. Dz.U. 2024 poz. 1251 ze zm.) art. 2, 4, 5, 9, 16-18a, 22, 25; rozporządzenie o znakach.
Q = [
("Na skrzyżowaniu bez znaków i sygnalizacji spotykasz samochód nadjeżdżający z twojej prawej strony. Kto jedzie pierwszy?",
 "Samochód z prawej strony", ["Ty, bo jedziesz szybciej", "Ten, kto pierwszy dojechał", "Ten, kto jedzie na wprost"],
 "Na skrzyżowaniu równorzędnym należy ustąpić pierwszeństwa pojazdowi nadjeżdżającemu z prawej strony (PoRD art. 25 ust. 1)."),
("Skręcasz w lewo na skrzyżowaniu równorzędnym. Z przeciwka nadjeżdża auto, które jedzie prosto. Co robisz?",
 "Ustępujesz mu pierwszeństwa", ["Jedziesz pierwszy, bo jest z lewej", "Jedziecie jednocześnie", "Mrugasz światłami i jedziesz"],
 "Skręcający w lewo ustępuje pierwszeństwa także jadącemu z kierunku przeciwnego na wprost lub skręcającemu w prawo (PoRD art. 25 ust. 1)."),
("Na skrzyżowaniu równorzędnym tramwaj nadjeżdża z twojej lewej strony. Kto ma pierwszeństwo?",
 "Tramwaj, bez względu na stronę", ["Ty, bo masz go po lewej", "Pojazd, który wjechał wcześniej", "Ty, jeśli jedziesz prosto"],
 "Pojazd szynowy ma pierwszeństwo przed innymi pojazdami bez względu na to, z której strony nadjeżdża (PoRD art. 25 ust. 2)."),
("Jedziesz drogą z pierwszeństwem i skręcasz w lewo. Z naprzeciwka, tą samą drogą, jedzie auto na wprost. Kto jedzie pierwszy?",
 "Auto jadące z naprzeciwka", ["Ty, bo masz pierwszeństwo", "Ten, kto zasygnalizował wcześniej", "Pojazd z drogi podporządkowanej"],
 "Obaj jesteście na drodze z pierwszeństwem, więc między wami obowiązuje art. 25 ust. 1 PoRD: skręcający w lewo ustępuje jadącemu z przeciwka na wprost."),
("Dojeżdżasz do znaku A-7 „ustąp pierwszeństwa”. Komu musisz ustąpić?",
 "Pojazdom na drodze z pierwszeństwem", ["Tylko pojazdom z prawej strony", "Tylko pojazdom z lewej strony", "Tylko tramwajom i autobusom"],
 "Znak A-7 ostrzega o skrzyżowaniu z drogą z pierwszeństwem: ustępujesz pojazdom poruszającym się tą drogą z obu kierunków (rozporządzenie o znakach, § 5 ust. 5)."),
("Pod znakiem A-7 widnieje tabliczka T-6c z pogrubioną linią pokazującą drogę główną. Komu ustępujesz pierwszeństwa?",
 "Jadącym drogą oznaczoną grubą linią", ["Wszystkim pojazdom na całym skrzyżowaniu", "Tylko pojazdom skręcającym w prawo", "Nikomu, bo tabliczka znosi znak"],
 "Tabliczka T-6c pod znakiem A-7 wskazuje rzeczywisty przebieg drogi z pierwszeństwem przez skrzyżowanie (§ 5 ust. 7 rozporządzenia o znakach); między pojazdami na drogach podporządkowanych obowiązuje zasada prawej ręki."),
("Wyjeżdżasz z parkingu przy sklepie na drogę publiczną. Jak nazywa się ten manewr i kto ma pierwszeństwo?",
 "Włączanie się do ruchu, ustępujesz", ["Skręt na skrzyżowaniu, więc prawa ręka", "Zmiana pasa, masz pierwszeństwo", "Zawracanie, więc jedziesz pierwszy"],
 "Wjazd na drogę z obiektu przydrożnego to włączanie się do ruchu; kierujący ustępuje pierwszeństwa innym pojazdom i uczestnikom ruchu (PoRD art. 17 ust. 1 pkt 1 i ust. 2)."),
("Wyjeżdżasz ze strefy zamieszkania na zwykłą ulicę. Kto ma pierwszeństwo?",
 "Pojazdy jadące tą ulicą", ["Ty, bo wyjeżdżasz z prawej", "Pojazd jadący szybciej", "Ten, kto pierwszy zatrąbi"],
 "Wjazd na drogę ze strefy zamieszkania jest włączaniem się do ruchu (PoRD art. 17 ust. 1 pkt 1), więc ustępujesz pierwszeństwa wszystkim jadącym tą drogą."),
("Z polnej drogi gruntowej wjeżdżasz na drogę asfaltową. Z lewej nadjeżdża samochód. Kto jedzie pierwszy?",
 "Samochód na asfalcie", ["Ty, bo jest po twojej lewej", "Ty, bo droga jest równorzędna", "Kierujący, który mrugnie światłami"],
 "Wjazd z drogi o nawierzchni gruntowej na drogę o nawierzchni twardej to włączanie się do ruchu (PoRD art. 17 ust. 1 pkt 2): ustępujesz pierwszeństwa, nawet pojazdom z lewej."),
("Zmieniasz pas ruchu w lewo. Komu musisz ustąpić pierwszeństwa?",
 "Jadącemu pasem, na który wjeżdżasz", ["Nikomu, jeśli włączysz kierunkowskaz", "Tylko pojazdom wolniejszym od ciebie", "Tylko pojazdom uprzywilejowanym"],
 "Zmieniając pas, ustępujesz pierwszeństwa pojazdowi jadącemu po pasie, na który zamierzasz wjechać, oraz wjeżdżającemu na ten pas z prawej strony (PoRD art. 22 ust. 4)."),
("Lewy pas się kończy, ruch jest bardzo powolny. Jedziesz prawym, ciągłym pasem. Jak masz postąpić?",
 "Wpuścić jedno auto na końcu pasa", ["Nie wpuszczać nikogo", "Wpuścić wszystkie auta z lewego pasa", "Zjechać na pobocze i przepuścić"],
 "Przy znacznym zmniejszeniu prędkości kierujący na sąsiednim pasie umożliwia zmianę pasa jednemu pojazdowi bezpośrednio przed miejscem zanikania pasa (jazda na suwak, PoRD art. 22 ust. 4a)."),
("Gdzie zgodnie z przepisami powinien nastąpić zjazd z kończącego się pasa przy jeździe na suwak?",
 "Na samym końcu pasa", ["Kilometr przed zwężeniem", "Zaraz po znaku ostrzegawczym", "Dopiero za zwężeniem, poboczem"],
 "Obowiązek umożliwienia zmiany pasa dotyczy miejsca bezpośrednio przed przeszkodą lub zanikaniem pasa (PoRD art. 22 ust. 4a), więc pas trzeba wykorzystać do końca."),
("Stoisz w korku na lewym z dwóch pasów jezdni. Gdzie zjeżdżasz, by utworzyć korytarz życia?",
 "Jak najbliżej lewej krawędzi pasa", ["Jak najbliżej prawej krawędzi pasa", "Na pas awaryjny po prawej stronie", "Na środek między oba pasy"],
 "Na jezdni z dwoma pasami w jednym kierunku jadący lewym pasem zjeżdża jak najbliżej lewej krawędzi, a jadący prawym jak najbliżej prawej (PoRD art. 9 ust. 2 pkt 1)."),
("Na jezdni z trzema pasami w jednym kierunku jedziesz środkowym pasem i robi się korek. Gdzie się przesuwasz?",
 "Do prawej krawędzi pasa", ["Do lewej krawędzi pasa", "Na lewy pas ruchu obok", "Zostajesz na środku pasa"],
 "Przy więcej niż dwóch pasach tylko skrajny lewy pas zjeżdża w lewo; kierujący na pozostałych pasach zjeżdżają jak najbliżej prawej krawędzi (PoRD art. 9 ust. 2 pkt 2)."),
("Ktoś jedzie korytarzem życia za karetką, żeby szybciej ominąć korek. Czy jest to dozwolone?",
 "Nie, korytarz jest tylko dla służb", ["Tak, jeśli jedzie za karetką", "Nie, chyba że korek trwa godzinę", "Tak, jeśli włączy światła awaryjne"],
 "Kierującemu pojazdem innym niż uprzywilejowany zabrania się korzystania z drogi przejazdu utworzonej dla pojazdu uprzywilejowanego (PoRD art. 9 ust. 3)."),
("Karetka ma włączone niebieskie światła błyskowe, ale nie ma syreny. Czy w świetle przepisów jest pojazdem uprzywilejowanym?",
 "Nie, potrzebne są też sygnały dźwiękowe", ["Tak, wystarczą niebieskie światła", "Tak, każda karetka jest uprzywilejowana", "Nie, chyba że jedzie powyżej 50 km/h"],
 "Pojazd uprzywilejowany wysyła jednocześnie niebieskie światła błyskowe i sygnały dźwiękowe o zmiennym tonie i jedzie z włączonymi światłami mijania lub drogowymi (PoRD art. 2 pkt 38). Ostrożność warto zachować i tak."),
("Słyszysz syrenę i widzisz niebieskie światła wozu straży pożarnej za sobą. Co musisz zrobić?",
 "Zjechać mu z drogi", ["Przyspieszyć, by uciec mu z drogi", "Zahamować gwałtownie na środku", "Jechać dalej jak dotąd"],
 "Uczestnik ruchu ułatwia przejazd pojazdu uprzywilejowanego, w szczególności przez niezwłoczne usunięcie się z jego drogi, a w razie potrzeby zatrzymanie się (PoRD art. 9 ust. 1)."),
("Rondo jest oznaczone tylko znakiem C-12 „ruch okrężny”, bez znaku A-7. Kto ma pierwszeństwo przy wjeździe?",
 "Pojazd wjeżdżający na rondo", ["Pojazd jadący po rondzie", "Pojazd większy", "Pojazd, który zasygnalizuje zjazd"],
 "Bez znaku A-7 rondo jest skrzyżowaniem równorzędnym i obowiązuje zasada prawej ręki (PoRD art. 25 ust. 1): wjeżdżający jest po prawej stronie jadących po rondzie."),
("W obszarze zabudowanym autobus na przystanku włącza lewy kierunkowskaz, chcąc odjechać. Co robisz?",
 "Zwalniam i umożliwiam mu odjazd", ["Przyspieszam, żeby go wyprzedzić", "Jadę dalej, mam pierwszeństwo", "Używam sygnału dźwiękowego"],
 "Zbliżając się do przystanku autobusowego na obszarze zabudowanym, należy zmniejszyć prędkość, a w razie potrzeby zatrzymać się, by autobus mógł włączyć się do ruchu (PoRD art. 18 ust. 1)."),
("Kierowca stojącego autobusu szkolnego podaje sygnał zatrzymania. Co robisz?",
 "Zatrzymuję się", ["Omijam autobus powoli", "Wyprzedzam go z lewej", "Zwalniam do 30 km/h"],
 "Zbliżając się do miejsca postoju autobusu szkolnego, kierujący zatrzymuje się, o ile kierujący autobusem podał sygnał zatrzymania (PoRD art. 18a ust. 1 pkt 1)."),
("Na parkingu twój tor jazdy przecina się z torem innego auta poza skrzyżowaniem. Jakie zasady stosujesz?",
 "Takie jak na skrzyżowaniu", ["Pierwszeństwo ma szybszy", "Pierwszeństwo ma większy", "Żadne przepisy nie obowiązują"],
 "Zasady pierwszeństwa z art. 25 ust. 1 i 2 PoRD stosuje się również w razie przecinania się kierunków ruchu poza skrzyżowaniem (art. 25 ust. 3)."),
("Czy wolno ci wjechać na skrzyżowanie, jeśli za nim nie ma miejsca na twoje auto?",
 "Nie, trzeba poczekać przed nim", ["Tak, przy zielonym świetle", "Tak, jeśli masz pierwszeństwo", "Nie, chyba że jedziesz drogą główną"],
 "Kierującemu zabrania się wjeżdżania na skrzyżowanie, jeżeli na skrzyżowaniu lub za nim nie ma miejsca do kontynuowania jazdy (PoRD art. 25 ust. 4 pkt 1)."),
("Jedziesz po torowisku tramwajowym i z tyłu nadjeżdża tramwaj. Co musisz zrobić?",
 "Zjechać z torowiska", ["Przyspieszyć do jego prędkości", "Zatrzymać się na torach", "Jechać dalej, masz pierwszeństwo"],
 "Kierujący pojazdem na części jezdni, po której jeżdżą pojazdy szynowe, ustępuje miejsca nadjeżdżającemu pojazdowi szynowemu (PoRD art. 16 ust. 6)."),
("Masz pierwszeństwo, ale widzisz, że kierowca z drogi podporządkowanej wjeżdża przed ciebie. Jak się zachowujesz?",
 "Hamuję, unikam zderzenia", ["Jadę dalej, bo mam rację", "Przyspieszam, by zdążyć", "Skręcam na chodnik"],
 "Możesz liczyć na przestrzeganie przepisów przez innych, chyba że okoliczności wskazują na możliwość odmiennego ich zachowania (zasada ograniczonego zaufania, PoRD art. 4)."),
("Na skrzyżowaniu działa sygnalizacja, a policjant wyciągnięciem ręki daje ci sygnał do zatrzymania przy zielonym świetle. Co robisz?",
 "Zatrzymuję się przed skrzyżowaniem", ["Jadę, bo mam zielone", "Jadę, jeśli nikt nie nadjeżdża", "Zatrzymuję się dopiero za skrzyżowaniem"],
 "Polecenia i sygnały osób kierujących ruchem mają pierwszeństwo przed sygnałami świetlnymi i znakami (PoRD art. 5 ust. 2)."),
("Na skrzyżowaniu z wyłączoną sygnalizacją stoją znaki D-1 i A-7. Według czego ustalasz pierwszeństwo?",
 "Według znaków", ["Według zasady prawej ręki", "Według wielkości pojazdów", "Według kolejności przybycia"],
 "Gdy sygnalizacja nie działa, obowiązują znaki drogowe regulujące pierwszeństwo (PoRD art. 5 ust. 1 i 3); prawa ręka obowiązuje dopiero wtedy, gdy nie ma ani sygnałów, ani znaków."),
("Wjeżdżasz na skrzyżowanie drogą z pierwszeństwem, a z prawej strony z drogi podporządkowanej nadjeżdża auto. Kto jedzie pierwszy?",
 "Ty, jadący drogą główną", ["Auto z prawej strony", "Ten, kto skręca w prawo", "Ten, kto szybciej dojechał"],
 "Kierujący z drogi podporządkowanej (znak A-7 lub B-20) ustępuje pierwszeństwa pojazdom na drodze z pierwszeństwem; zasada prawej ręki z art. 25 ust. 1 PoRD ustępuje znakom (art. 5 ust. 1)."),
("Dwa pojazdy wjeżdżają na skrzyżowanie równorzędne, a z prawej strony jednego z nich nadjeżdża autobus miejski. Czy autobus ma szczególne pierwszeństwo?",
 "Nie, obowiązuje zasada prawej ręki", ["Tak, autobus zawsze jedzie pierwszy", "Nie, ustępuje wszystkim autom", "Tak, ale tylko w godzinach szczytu"],
 "Szczególne pierwszeństwo na skrzyżowaniu równorzędnym ma tylko pojazd szynowy (PoRD art. 25 ust. 2); autobus podlega ogólnej zasadzie prawej ręki."),
("Ruszasz z pobocza i wracasz na jezdnię. Kto ma pierwszeństwo?",
 "Pojazdy jadące jezdnią", ["Ty, bo ruszasz z prawej", "Ty, jeśli włączysz kierunkowskaz", "Ten, kto jedzie wolniej"],
 "Wjazd na jezdnię z pobocza to włączanie się do ruchu (PoRD art. 17 ust. 1 pkt 3); kierujący ustępuje pierwszeństwa innym pojazdom i uczestnikom ruchu (art. 17 ust. 2)."),
("Skręcasz w lewo z drogi podporządkowanej na drogę z pierwszeństwem. Z lewej i z prawej jadą auta drogą główną. Komu ustępujesz?",
 "Pojazdom z obu kierunków", ["Tylko pojazdom z prawej", "Tylko pojazdom z lewej", "Tylko pojazdom skręcającym"],
 "Znak A-7 lub B-20 nakazuje ustąpić pierwszeństwa kierującym poruszającym się drogą z pierwszeństwem, bez względu na kierunek, z którego nadjeżdżają (rozporządzenie o znakach, § 5 ust. 5 i § 21 ust. 1)."),
("Na skrzyżowaniu równorzędnym ty jedziesz prosto, a z lewej strony nadjeżdża samochód, który skręca w prawo. Kto jedzie pierwszy?",
 "Ty, bo on jest z lewej", ["Samochód z lewej strony", "Ten, kto skręca w prawo", "Jedziecie jednocześnie"],
 "Na skrzyżowaniu równorzędnym ustępuje się pojazdowi nadjeżdżającemu z prawej (PoRD art. 25 ust. 1); kierujący z lewej musi ustąpić tobie."),
]
